/* XAHBall - shared look of the menu-style screens: stadium backdrop
 * (res/menu/menubg.png, generated by tools/make_menu_bg.py from the title
 * master art) + framed panels.
 */
#include "ui.h"

#include <ace/managers/blit.h>
#include <ace/managers/joy.h>
#include <ace/managers/key.h>
#include <ace/managers/log.h>
#include "game.h"

// OCS BLTSIZE height is 10 bits and an interleaved blit runs height*depth
// rows - copy the full screen in bands that stay well below 1024 rows
#define UI_COPY_BAND 128

static tBitMap *s_pBackdrop;

void uiCreate(void) {
	s_pBackdrop = bitmapCreateFromPath("data/menubg.bm", 0);
	if(!s_pBackdrop) {
		logWrite("ERR: data/menubg.bm failed to load - flat menu backdrop\n");
	}
	else if(!bitmapIsInterleaved(s_pBackdrop) || s_pBackdrop->Depth != GAME_BPP) {
		logWrite("ERR: menubg.bm must be interleaved %hhu bpp\n", (UBYTE)GAME_BPP);
	}
}

void uiDestroy(void) {
	if(s_pBackdrop) {
		bitmapDestroy(s_pBackdrop);
		s_pBackdrop = 0;
	}
}

void uiRestoreBackdrop(tBitMap *pDst, UWORD uwX, UWORD uwY, UWORD uwW, UWORD uwH) {
	if(!s_pBackdrop) {
		blitRect(pDst, uwX, uwY, uwW, uwH, COLOR_BG);
		return;
	}
	for(UWORD uwDone = 0; uwDone < uwH; uwDone += UI_COPY_BAND) {
		UWORD uwBand = uwH - uwDone;
		if(uwBand > UI_COPY_BAND) {
			uwBand = UI_COPY_BAND;
		}
		blitCopyAligned(
			s_pBackdrop, uwX, uwY + uwDone, pDst, uwX, uwY + uwDone, uwW, uwBand
		);
	}
}

void uiDrawBackdrop(tBitMap *pDst) {
	uiRestoreBackdrop(pDst, 0, 0, GAME_SCREEN_WIDTH, GAME_SCREEN_HEIGHT);
}

void uiDrawPanel(
	tBitMap *pDst, UWORD uwX, UWORD uwY, UWORD uwW, UWORD uwH, UBYTE ubHighlight
) {
	UBYTE ubFrame = ubHighlight ? COLOR_AMBER : COLOR_GRAY;
	blitRect(pDst, uwX, uwY, uwW, uwH, COLOR_PANEL);
	blitRect(pDst, uwX, uwY, uwW, 1, ubFrame);
	blitRect(pDst, uwX, uwY + uwH - 1, uwW, 1, ubFrame);
	blitRect(pDst, uwX, uwY, 1, uwH, ubFrame);
	blitRect(pDst, uwX + uwW - 1, uwY, 1, uwH, ubFrame);
}

tUiNav uiNavPoll(void) {
	if(keyUse(KEY_UP) || keyUse(KEY_W) || joyUse(JOY1_UP)) {
		return UI_NAV_UP;
	}
	if(keyUse(KEY_DOWN) || keyUse(KEY_S) || joyUse(JOY1_DOWN)) {
		return UI_NAV_DOWN;
	}
	if(keyUse(KEY_LEFT) || keyUse(KEY_A) || joyUse(JOY1_LEFT)) {
		return UI_NAV_LEFT;
	}
	if(keyUse(KEY_RIGHT) || keyUse(KEY_D) || joyUse(JOY1_RIGHT)) {
		return UI_NAV_RIGHT;
	}
	if(keyUse(KEY_RETURN) || keyUse(KEY_SPACE) || keyUse(KEY_X) || joyUse(JOY1_FIRE)) {
		return UI_NAV_FIRE;
	}
	if(keyUse(KEY_ESCAPE)) {
		return UI_NAV_BACK;
	}
	return UI_NAV_NONE;
}

UBYTE uiAnyInput(void) {
	UBYTE ubAny = joyUse(JOY1_FIRE) | joyUse(JOY2_FIRE);
	for(UWORD i = 0; i < KEY_COUNT; ++i) {
		if(g_sKeyManager.pStates[i] == KEY_ACTIVE) {
			g_sKeyManager.pStates[i] = KEY_USED;
			ubAny = 1;
		}
	}
	return ubAny;
}
